import {DEFAULT_RULES,normalize,compute,fromCSV,parseCell,csvEscape} from './engine.js';
import {demoContest} from './demo.js';
const $=(s)=>document.querySelector(s), esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={chart:'M3 3v18h18M7 14l4-4 4 3 5-7M16 6h4v4',archive:'M4 8h16v12H4zM3 4h18v4H3zM9 12h6',sliders:'M4 6h16M4 12h16M4 18h16M9 3v6M15 9v6M8 15v6',book:'M12 5c-4-3-9-1-9-1v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1zm0 0v15',shield:'M12 3l8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6zM8 12l3 3 5-6',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',trophy:'M7 3h10v7a5 5 0 0 1-10 0zm0 2H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 3v6m-4 0h8',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m8-7a4 4 0 0 1 0 7m5 11v-3a4 4 0 0 0-4-4',building:'M4 21V3h12v18M16 9h4v12M8 7h4M8 11h4M8 15h4M9 21v-3h2v3',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',unlock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0m-4 9v2',info:'M12 11v6m0-10v1m9 4a9 9 0 1 1-18 0 9 9 0 0 1 18 0',search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'m8 4 12 8-12 8z',pause:'M8 4v16M16 4v16',refresh:'M20 8a8 8 0 1 0 0 8m0-13v5h-5',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8m-8 4h6',check:'m5 12 4 4L20 5',chevron:'m9 5 7 7-7 7'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.info}"/></svg>`;
const icons=()=>document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const formatTime=(n)=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
let contests=[demoContest()],rules={...DEFAULT_RULES},currentId='demo-2026',page='standings',time=185,traditional=false,final=false,schoolMode=false,query='',officialOnly=false,pageIndex=1,timer=null,speed=5,pendingImport=null;
let storageWarning=false;
try{const saved=JSON.parse(localStorage.getItem('ccpc-rank-v1')||'null');if(saved){contests=saved.contests.map(normalize);if(!contests.length)contests=[demoContest()];currentId=contests.some(c=>c.id===saved.currentId)?saved.currentId:contests[0].id;const r=saved.rules||{};for(const k of ['penalty','threshold','percent','freeze'])if(Number.isFinite(r[k])&&r[k]>0)rules[k]=r[k];}}catch{storageWarning=true;}
const active=()=>contests.find(c=>c.id===currentId)||contests[0];
const state=()=>compute(active(),time,rules,{traditional,final});
let currentState=state();
function persist(){try{localStorage.setItem('ccpc-rank-v1',JSON.stringify({contests,rules,currentId}));return true;}catch{toast('浏览器存储空间不足，当前数据仅保留在本次会话，请导出备份');return false;}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function stop(){if(timer)clearInterval(timer);timer=null;const el=$('#play');if(el){el.innerHTML=icon('play');el.setAttribute('aria-label','播放回放');}}
function goto(p){stop();page=p;query='';pageIndex=1;document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#breadcrumb').textContent={standings:'动态榜单',history:'历史赛事',rules:'赛制规则',guide:'导入指南'}[p];$('#history-count').textContent=contests.length;render();icons();window.scrollTo({top:0,behavior:'instant'});}
const title=(eyebrow,name,description,buttons='')=>`<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p>${description}</p></div><div class="title-buttons">${buttons}</div></div>`;
const importButton=()=>`<button class="button primary" data-action="import">${icon('upload')} 导入历史榜单</button>`;
function render(){if(page==='standings')renderStandings();else if(page==='history')renderHistory();else if(page==='rules')renderRules();else renderGuide();}
function renderStandings(){
 const c=active();currentState=state();
 $('#main').innerHTML=title('CONTEST WORKSPACE','动态榜单','让历史赛事，在新赛制下重新发生。',`<button class="button secondary" data-action="export">${icon('download')} 导出榜单</button>${importButton()}`)+`
 <section class="contest-strip"><div class="contest-ident"><div class="contest-mark">${icon('trophy')}</div><div><h2>${esc(c.title)}<span class="tag">${c.id==='demo-2026'?'演示赛事':'已导入'}</span></h2><small>${esc(c.source)} <span class="footer-dot">·</span> ${c.problems.length} 道题目 <span class="footer-dot">·</span> ${formatTime(c.duration)} 小时</small></div></div><div class="contest-meta"><span>${icon('file')} ${c.submissions?'提交级数据':'最终快照'}</span><select id="contest-select" class="contest-picker" aria-label="切换赛事">${contests.map(x=>`<option value="${esc(x.id)}" ${x.id===c.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div></section>
 <section class="metrics" id="metrics" aria-label="榜单统计"></section>
 <section class="timeline"><div class="timeline-top"><div class="timeline-label"><i>${icon('clock')}</i>${currentState.replay?'比赛时间线':'最终榜单快照'}<span class="subtle-tag">${currentState.replay?'HISTORY REPLAY':'SNAPSHOT'}</span></div><div class="timeline-controls"><span class="time-current mono" id="time-label">${formatTime(time)}</span><span>/ ${formatTime(c.duration)}</span>${currentState.replay?`<select id="speed" aria-label="播放速度"><option value="1">1×</option><option value="5" selected>5×</option><option value="15">15×</option></select><button id="play" class="play-btn" aria-label="播放回放">${icon('play')}</button><button id="reset-time" class="play-btn" aria-label="回到开赛">${icon('refresh')}</button>`:''}</div></div>
 ${currentState.replay?`<div class="timeline-track"><input id="timeline" type="range" min="0" max="${c.duration}" value="${time}" step="1" aria-label="比赛已进行分钟数"><div class="time-marks">${[0,c.duration/5,c.duration*2/5,c.duration*3/5,c.duration*4/5,c.duration].map((n,i)=>`<span>${formatTime(n)}${i===4&&rules.freeze===240&&c.duration===300?' · 封榜':''}</span>`).join('')}</div></div>`:''}<div id="rule-banner"></div></section>
 <section class="scoreboard"><div class="board-top"><div class="board-tabs"><button class="board-tab ${!schoolMode?'active':''}" data-board="team">队伍榜单 <small>${c.teams.length}</small></button><button class="board-tab ${schoolMode?'active':''}" data-board="school">学校榜单</button></div><div class="board-tools"><label class="search">${icon('search')}<input id="search" placeholder="搜索队伍 / 学校" aria-label="搜索队伍或学校" value="${esc(query)}"><span class="kbd">/</span></label><label class="check-label"><input id="official-only" type="checkbox" ${officialOnly?'checked':''}>仅正式队伍</label><div class="mode-switch"><button data-mode="dynamic" class="${!traditional?'active':''}">动态榜</button><button data-mode="traditional" class="${traditional?'active':''}">传统榜</button></div></div></div><div class="table-wrap" id="table-wrap"></div><div class="board-bottom"><div class="legend"><span><b class="legend-dot first"></b>一血</span><span><b class="legend-dot"></b>已通过</span><span><b class="legend-dot wrong"></b>未通过</span><span><b class="legend-dot hidden"></b>未公开</span></div><div class="pagination" id="pagination"></div></div></section><div class="bottom-note"><span>${icon('info')} ${currentState.replay?'逐条提交回放；编译错误不计罚时，未通过题不计总罚时。':'此数据不含完整提交记录，仅展示最终成绩；不推测历史过程。'}</span><span>${icon('shield')} 浏览器本地保存 <span class="footer-dot">·</span> ${c.id==='demo-2026'?'当前为模拟数据':'导入文件不会上传'}</span></div>`;
 refresh();
 $('#search').addEventListener('input',e=>{query=e.target.value;pageIndex=1;renderTable();});
 $('#official-only').addEventListener('change',e=>{officialOnly=e.target.checked;pageIndex=1;renderTable();});
 $('#contest-select').addEventListener('change',e=>selectContest(e.target.value));
 $('#timeline')?.addEventListener('input',e=>{stop();time=Number(e.target.value);final=false;pageIndex=1;refresh();});
 $('#speed')?.addEventListener('change',e=>speed=Number(e.target.value));
 $('#play')?.addEventListener('click',()=>{if(timer){stop();return;}if(time>=c.duration)time=0;final=false;$('#play').innerHTML=icon('pause');$('#play').setAttribute('aria-label','暂停回放');timer=setInterval(()=>{time=Math.min(time+speed,c.duration);$('#timeline').value=time;refresh();if(time>=c.duration)stop();},500);});
 $('#reset-time')?.addEventListener('click',()=>{stop();time=0;final=false;$('#timeline').value=0;refresh();});
}
function refresh(){
 currentState=state();const s=currentState,c=active(),schools=new Set(c.teams.map(t=>t.school)).size;
 $('#metrics').innerHTML=[['参赛队伍',s.total,'支',`${s.rows.filter(r=>!r.unofficial).length} 支正式队伍 · ${s.rows.filter(r=>r.unofficial).length} 支打星队伍`,'users'],['参赛学校',schools,'所','每所学校取最高正式队伍成绩','building'],['已公开题目',s.open,`/ ${c.problems.length}`,`${c.problems.length-s.open} 道题目等待动态揭榜`,'unlock'],['当前比赛状态',final?'已揭榜':s.frozen?'封榜中':s.replay?'回放中':'最终榜','',final?'展示赛后完整结果':s.frozen?'题目已公开 · 封榜后提交隐藏':s.replay?`已进行 ${formatTime(time)} · 非实时比赛`:'不含历史提交记录','clock']].map((m,i)=>`<article class="metric ${i===2?'emphasis':''}"><div class="metric-label">${m[0]}<i>${icon(m[4])}</i></div><div class="metric-value ${i===3?'status-value':''}" ${i===3?'style="font-size:24px;line-height:1.7"':''}>${m[1]}<small>${m[2]}</small></div><div class="metric-caption">${i===3?'<span class="dot"></span>':''}${m[3]}</div></article>`).join('');
 $('#time-label').textContent=formatTime(s.replay?time:c.duration);
 $('#rule-banner').innerHTML=`<div class="rule-banner ${!s.replay?'snapshot-note':''}"><i>${icon(s.frozen?'lock':'info')}</i><span>${!s.replay?'最终快照：已按赛后完整榜展示，无法从快照恢复提交过程。':final?'已揭开封榜后的全部提交，展示最终排名。':s.frozen?`第 ${rules.freeze} 分钟已公开所有题目；总成绩保留在封榜前，后续提交显示为待揭榜。`:`动态揭榜：单题通过达到 <strong>${rules.threshold} 队</strong> 或 <strong>${rules.percent}%</strong>（本场 ${s.revealCount} 队）即公开，<strong>${formatTime(rules.freeze)}</strong> 起全部公开。`}</span>${s.replay&&time>=rules.freeze&&!final?'<button class="text-button" data-action="reveal" style="margin-left:auto;white-space:nowrap">查看最终榜 →</button>':'<a href="#rules" data-action="rules">查看规则 ↗</a>'}</div>`;
 renderTable();
}
function visibleRows(){let rows=currentState.rows;if(officialOnly)rows=rows.filter(r=>!r.unofficial);if(schoolMode){const seen=new Set();rows=rows.filter(r=>{if(r.unofficial||seen.has(r.school))return false;seen.add(r.school);return true;}).map((r,i)=>({...r,rank:i+1}));}const q=query.trim().toLowerCase();if(q)rows=rows.filter(r=>(r.name+' '+r.school).toLowerCase().includes(q));return rows;}
const colors=['#d7af83','#9eb6cc','#bc91a6','#b2bb8a','#a0c6b1','#ac9bc7','#d9b970','#98b9ae','#cba694','#9eaac4','#a0bb84','#c4a9c8'];
function cell(c,p){if(!p.open)return `<div class="result hidden" title="此题尚未公开，所有队伍统一隐藏">${icon('lock')}</div>`;if(c.solved)return `<div class="result ${c.time===p.first?'first':'ac'}" title="${c.time===p.first?'最早通过 · ':''}通过于 ${formatTime(c.time)}，此前 ${c.wrong} 次计罚错误"><span>+${c.wrong||''}</span><small class="mono">${Math.floor(c.time)} min</small></div>`;if(c.pending)return `<div class="result pending" title="有 ${c.pending} 条待揭榜提交">?${c.pending}</div>`;if(c.wrong)return `<div class="result wrong" title="${c.wrong} 次未通过提交">−${c.wrong}</div>`;return '<div class="result empty">·</div>';}
function renderTable(){
 const s=currentState,all=visibleRows(),perPage=15,totalPages=Math.max(1,Math.ceil(all.length/perPage));pageIndex=Math.min(pageIndex,totalPages);const rows=all.slice((pageIndex-1)*perPage,pageIndex*perPage);
 const scroll=$('#table-wrap').scrollTop;
 $('#table-wrap').innerHTML=`<table aria-label="${schoolMode?'学校':'队伍'}竞赛榜单"><thead><tr><th class="rank-col">排名</th><th class="team-col">${schoolMode?'学校 / 代表队伍':'队伍 / 学校'}</th><th class="solved-col">解题</th><th class="penalty-col">罚时</th>${s.stats.map((p,i)=>`<th class="problem-col"><div class="problem-head ${p.open?'':'locked'}">${p.open?`<span class="balloon-dot" style="background:${colors[i%12]}"></span>`:icon('lock')}${esc(p.id)}</div><span class="problem-meta ${p.open?'':'hidden-meta'}">${p.open?`${p.solved} / ${s.total}`:'未公开'}</span></th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td class="rank-col">${typeof r.rank==='number'&&r.rank<=3?`<span class="rank-medal ${r.rank===2?'silver':r.rank===3?'bronze':''}">${r.rank}</span>`:r.rank}</td><td class="team-col"><button class="team-name" data-team="${esc(r.id)}">${esc(schoolMode?r.school:r.name)}${r.unofficial?'<span class="star-tag">打星</span>':''}</button><span class="school-name">${esc(schoolMode?r.name:r.school)}</span></td><td><span class="solved-number mono">${r.solved}</span></td><td><span class="penalty-number mono">${r.penalty}</span></td>${s.stats.map(p=>`<td class="result-cell">${cell(r.cells[p.id],p)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${4+s.stats.length}"><div class="empty-state"><strong>没有找到匹配的队伍</strong>试试其他队名或学校名称。</div></td></tr>`}</tbody></table>`;
 $('#table-wrap').scrollTop=scroll;
 $('#pagination').innerHTML=`<span style="margin-right:8px">共 ${all.length} ${schoolMode?'所学校':'支队伍'}</span><button data-pagination="${pageIndex-1}" ${pageIndex===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:Math.min(totalPages,5)},(_,i)=>{const p=Math.max(1,Math.min(pageIndex-2,totalPages-4))+i;return `<button data-pagination="${p}" class="${pageIndex===p?'active':''}">${p}</button>`;}).join('')}<button data-pagination="${pageIndex+1}" ${pageIndex===totalPages?'disabled':''} aria-label="下一页">›</button><span style="margin-left:5px">${pageIndex} / ${totalPages}</span>`;
}
function selectContest(id){stop();currentId=id;time=active().submissions?Math.min(185,active().duration):active().duration;final=!active().submissions;pageIndex=1;persist();goto('standings');}
function renderHistory(){
 $('#main').innerHTML=title('CONTEST ARCHIVE','历史赛事','每一场竞赛，都有值得重看的瞬间。',importButton())+contests.map(c=>`<article class="history-card"><div class="contest-ident"><div class="contest-mark">${icon('archive')}</div><div><h3>${esc(c.title)} <span class="tag">${c.id==='demo-2026'?'演示':'已导入'}</span></h3><p>${c.teams.length} 支队伍 · ${c.problems.length} 道题目 · ${c.submissions?`${c.submissions.length} 条提交 · 可完整回放`:'最终快照'}<br>${esc(c.source)}</p></div></div><div class="history-actions"><button class="button secondary small" data-backup="${esc(c.id)}">备份数据</button>${c.id!=='demo-2026'?`<button class="button secondary small" data-delete="${esc(c.id)}">移除</button>`:''}<button class="button primary small" data-open="${esc(c.id)}">${c.submissions?'进入回放':'查看榜单'} →</button></div></article>`).join('')+'<div class="source-note">数据保存在当前浏览器。更换设备、浏览器或清除站点数据后不会自动同步，请使用「备份数据」保存原始 JSON。</div>';
}
function renderRules(){
 $('#main').innerHTML=title('A LITTLE MORE SUSPENSE','赛制规则','排名照常发生，悬念在题号之间保留。')+`<section class="content-panel"><span class="eyebrow">DYNAMIC SCOREBOARD</span><h2 style="margin-top:12px">三个条件，任一满足即公开题目</h2><p>未达到条件时，所有队伍对应题目的单元格及通过数统一隐藏。队伍仍按总解题数降序、总罚时升序排名。</p><div class="rule-grid"><article class="rule-card"><div class="rule-number">${rules.threshold}<small style="font-size:12px"> 队</small></div><h3>达到绝对通过阈值</h3><p>通过该题的队伍数达到阈值。</p></article><article class="rule-card"><div class="rule-number">${rules.percent}%</div><h3>达到参赛队伍占比</h3><p>按全部导入队伍计算，人数向上取整。</p></article><article class="rule-card"><div class="rule-number">${formatTime(rules.freeze)}</div><h3>进入常规封榜时间</h3><p>全部题目公开；此后的提交待赛后揭榜。</p></article></div><div class="source-note">规则依据：<a href="https://codeforces.com/gym/106725/problem/N" target="_blank" rel="noreferrer">2026 CCPC Online · N. New CCPC Rule ↗</a>。题面注明该方案在当时尚未最终定稿，也未用于网络赛。本工具默认使用题面中的 50 队、20%、240 分钟；可调整参数模拟其他版本。</div></section><section class="content-panel"><h2>实验参数</h2><p>修改后立即应用于当前工作空间中的所有赛事。自定义设置属于赛制模拟。</p><form id="rule-form"><div class="rule-form"><div class="field"><label for="threshold">单题通过阈值 / 队</label><input id="threshold" name="threshold" type="number" min="1" max="20000" step="1" value="${rules.threshold}" required></div><div class="field"><label for="percent">通过比例 / %</label><input id="percent" name="percent" type="number" min="0.01" max="100" step="0.01" value="${rules.percent}" required></div><div class="field"><label for="freeze">封榜起点 / 分钟</label><input id="freeze" name="freeze" type="number" min="1" max="10080" value="${rules.freeze}" required></div><div class="field"><label for="penalty">每次错误罚时 / 分钟</label><input id="penalty" name="penalty" type="number" min="0" max="1000" value="${rules.penalty}" required></div></div><div class="form-actions"><button type="submit" class="button primary">保存并应用</button><button type="button" class="button secondary" data-action="reset-rules">恢复题面默认值</button></div></form></section><section class="content-panel"><h2>回放与排名细则</h2><p>先比较已解题数，再比较总罚时；两者相同采用并列名次。罚时以每题首次 AC 的分钟数向下取整，加上 AC 之前的计罚错误次数 × 错误罚时。CE、待评测及忽略记录不计罚时；赛末及赛末后的提交不计入比赛。打星队伍参与榜单显示与揭榜阈值统计，不占正式队伍名次。学校榜单取各校最高正式队伍。<br>进入封榜时公开所有题目，但第 ${rules.freeze} 分钟（含）之后的提交仅显示待揭榜状态。选择「查看最终榜」可揭开赛末前全部提交。仅有最终成绩的文件不会被用于历史回放。<br>本工具用于导入后的本地分析。原始成绩存于浏览器，动态隐藏仅影响显示和当前榜单导出。</p></section>`;
 $('#rule-form').addEventListener('submit',e=>{e.preventDefault();for(const key of ['threshold','percent','freeze','penalty'])rules[key]=Number(e.target.elements[key].value);final=false;persist();toast('赛制参数已保存，所有赛事已应用');renderRules();});
}
const template={title:'我的历史赛事',duration:300,problems:['A','B','C'],teams:[{id:'1',name:'Hello World',school:'示例大学'},{id:'2',name:'无限可能',school:'另一所大学'}],submissions:[{teamId:'1',problemId:'A',time:15,verdict:'WA'},{teamId:'1',problemId:'A',time:28,verdict:'AC'},{teamId:'2',problemId:'B',time:43,verdict:'AC'}]};
function renderGuide(){
 $('#main').innerHTML=title('YOUR DATA, A NEW VIEW','导入指南','保留原始成绩，用动态规则重现比赛。',importButton())+`<div class="guide-columns"><section class="content-panel"><h2>01 / 提交级数据 · 推荐</h2><p>支持 JSON 或提交 CSV。时间为比赛开始后的分钟数，可用小数表示秒；结束时刻本身的提交不计分。每条提交包含队伍 ID、题目 ID、时间和判定。</p><pre class="code-block">${esc(JSON.stringify(template,null,2))}</pre><button class="button secondary" data-action="template">${icon('download')} 下载 JSON 模板</button></section><div><section class="content-panel"><h2>02 / 历史榜单 CSV</h2><p>支持 UTF-8 CSV / TSV，可从 Excel 另存为 CSV UTF-8。必要列为 name（或「队名」）和题目字母 A、B、C…；school（或「学校」）可选。</p><pre class="code-block">name,school,A,B,C\nHello World,示例大学,+1 00:28,,-2\n无限可能,另一所大学,,+ 00:43,</pre><p><b>+1 00:28</b>：28 分钟通过，此前 1 次错误。<br><b>+ 43</b>：43 分钟首次通过。<br><b>-2</b>：2 次错误，尚未通过。空白：无提交。<br>CSV / HTML 最终榜单以快照导入，无法恢复完整回放。</p><button class="button secondary" style="margin-top:18px" data-action="csv-template">${icon('download')} 下载 CSV 模板</button></section><section class="content-panel" style="margin-top:20px"><h2>03 / HTML 和提交 CSV</h2><p>HTML 支持包含标准表格的静态榜单文件，表头需有 Who / Team / 队名及 A、B、C…列，题目单元格按上述格式读取。不执行文件中的脚本。不支持图片、PDF 或仅有页面框架的动态 HTML。</p><pre class="code-block">teamId,name,school,problemId,time,verdict\n1,Hello World,示例大学,A,15,WA\n1,Hello World,示例大学,A,28,AC\n2,无限可能,另一所大学,B,43,AC</pre><p>支持 AC、WA、TLE、RE、MLE、OLE、PE、CE、PD、IGNORED 及常见英文全称。CE 不计罚时。原始 JSON 可添加 unofficial: true 标记打星队伍。</p></section></div></div><div class="source-note">文件上限 20 MB，最多 20,000 支队伍、100 道题、500,000 条提交。导入前会验证队伍、题目引用和时间格式；原始数据不会上传到服务器。榜单导出遵循当前动态显示规则，历史赛事中的「备份数据」则保留全部原始数据。</div>`;
}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[<>:"/\\|?*]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBoard(){const s=currentState;const header=['排名','队伍','学校','解题数','罚时',...s.stats.map(p=>p.id)];const lines=visibleRows().map(r=>[r.rank,r.name,r.school,r.solved,r.penalty,...s.stats.map(p=>{const c=r.cells[p.id];return !p.open?'未公开':c.solved?`AC (${c.wrong} WA) ${Math.floor(c.time)} min`:c.pending?`待揭榜 ${c.pending}`:c.wrong?`WA ${c.wrong}`:'';})]);download('\uFEFF'+[header,...lines].map(row=>row.map(csvEscape).join(',')).join('\r\n'),`${active().title}-${formatTime(time).replace(':','-')}-${final?'最终':traditional?'传统':'动态'}榜.csv`,'text/csv;charset=utf-8');toast('已导出当前筛选范围的榜单，未公开题目保持隐藏');}
function showTeam(id){const s=currentState,r=s.rows.find(x=>x.id===id);if(!r)return;$('#team-title').textContent=r.name;$('#team-body').innerHTML=`<p class="muted">${esc(r.school)} ${r.unofficial?'· 打星队伍':''}</p><div class="detail-grid"><div class="detail-stat">当前名次<strong>${r.rank}</strong></div><div class="detail-stat">解题数<strong>${r.solved}</strong></div><div class="detail-stat">总罚时<strong>${r.penalty}</strong></div></div><div class="detail-problems">${s.stats.map(p=>`<div>${esc(p.id)}${cell(r.cells[p.id],p)}</div>`).join('')}</div><p class="muted" style="font-size:10px;margin-top:20px">未公开题目与主榜保持一致，详情不会提前展示隐藏成绩。</p>`;$('#team-dialog').showModal();}
function showImport(){stop();pendingImport=null;$('#import-preview').innerHTML='';$('#import-error').textContent='';$('#confirm-import').disabled=true;$('#file-input').value='';$('#paste-input').value='';$('#import-dialog').showModal();}
function parseHTML(text,title){const doc=new DOMParser().parseFromString(text,'text/html');for(const table of doc.querySelectorAll('table')){const rows=[...table.rows];const index=rows.findIndex(r=>[...r.cells].some(c=>/^(Who|Team|Name|队名|队伍)$/i.test(c.textContent.trim()))&&[...r.cells].some(c=>/^[A-Z]$/.test(c.textContent.trim())));if(index<0)continue;const headers=[...rows[index].cells].map(c=>c.textContent.trim());const nameIndex=headers.findIndex(h=>/^(Who|Team|Name|队名|队伍)$/i.test(h));const schoolIndex=headers.findIndex(h=>/^(school|学校)$/i.test(h));const ps=headers.map((h,i)=>({id:h,index:i})).filter(p=>/^[A-Z]$/.test(p.id));const teams=rows.slice(index+1).filter(r=>r.cells.length>=headers.length).map((r,i)=>({id:String(i+1),name:r.cells[nameIndex].textContent.trim(),school:schoolIndex<0?'未填写学校':r.cells[schoolIndex].textContent.trim(),results:Object.fromEntries(ps.map(p=>[p.id,parseCell(r.cells[p.index].textContent.trim().replace(/\s+/g,' '))]))}));return normalize({title,teams,problems:ps.map(p=>p.id),source:'HTML 静态榜单'});}throw Error('未找到可识别的标准榜单表格，请使用 JSON 或 CSV 模板');}
function parseData(text,name='粘贴的历史榜单'){try{if(!text.trim())throw Error('请先选择文件或粘贴数据');let c;const trimmed=text.trim().replace(/^\uFEFF/,'');if(trimmed.startsWith('{')||trimmed.startsWith('['))c=normalize(JSON.parse(trimmed));else if(/<!doctype|<html|<table/i.test(trimmed))c=parseHTML(trimmed,name.replace(/\.[^.]+$/,''));else c=fromCSV(trimmed,name.replace(/\.[^.]+$/,''));if(c.id==='demo-2026'||contests.some(x=>x.id===c.id))c.id=crypto.randomUUID();pendingImport=c;$('#import-preview').innerHTML=`<div class="import-preview-card"><strong>${esc(c.title)}</strong><small>✓ 验证通过 · ${c.teams.length} 支队伍 · ${c.problems.length} 道题目${c.submissions?` · ${c.submissions.length} 条提交`:' · 最终快照'}</small><small>${c.submissions?'含完整提交时间，可进行动态揭榜回放。':'不含提交记录，将直接展示最终快照，不提供时间回放。'}</small></div>`;$('#import-error').textContent='';$('#confirm-import').disabled=false;}catch(e){pendingImport=null;$('#import-preview').innerHTML='';$('#import-error').textContent=e.message;$('#confirm-import').disabled=true;}}
async function readFile(file){if(!file)return;if(file.size>20*1024*1024){$('#import-error').textContent='文件超过 20 MB，请拆分数据后导入';pendingImport=null;$('#confirm-import').disabled=true;return;}try{parseData(await file.text(),file.name);}catch{$('#import-error').textContent='文件读取失败，请重试';}}
document.addEventListener('click',e=>{
 const pageButton=e.target.closest('[data-page]');if(pageButton){goto(pageButton.dataset.page);return;}
 const board=e.target.closest('[data-board]');if(board){stop();schoolMode=board.dataset.board==='school';pageIndex=1;renderStandings();return;}
 const mode=e.target.closest('[data-mode]');if(mode){stop();traditional=mode.dataset.mode==='traditional';renderStandings();return;}
 const pg=e.target.closest('[data-pagination]');if(pg&&!pg.disabled){pageIndex=Number(pg.dataset.pagination);renderTable();$('#table-wrap').scrollTop=0;return;}
 const team=e.target.closest('[data-team]');if(team){showTeam(team.dataset.team);return;}
 const open=e.target.closest('[data-open]');if(open){selectContest(open.dataset.open);return;}
 const backup=e.target.closest('[data-backup]');if(backup){const c=contests.find(x=>x.id===backup.dataset.backup);download(JSON.stringify(c,null,2),`${c.title}.json`);return;}
 const del=e.target.closest('[data-delete]');if(del){const c=contests.find(x=>x.id===del.dataset.delete);if(confirm(`移除「${c.title}」？建议先备份数据。`)){contests=contests.filter(x=>x.id!==c.id);if(!contests.length)contests=[demoContest()];if(currentId===c.id)currentId=contests[0].id;persist();goto('history');toast('已移除赛事');}return;}
 const tab=e.target.closest('[data-import-tab]');if(tab){document.querySelectorAll('[data-import-tab]').forEach(b=>b.classList.toggle('active',b===tab));$('#file-pane').hidden=tab.dataset.importTab!=='file';$('#paste-pane').hidden=tab.dataset.importTab!=='paste';return;}
 const action=e.target.closest('[data-action]');if(!action)return;e.preventDefault();switch(action.dataset.action){case'import':showImport();break;case'export':exportBoard();break;case'rules':goto('rules');break;case'reveal':stop();time=active().duration;final=true;if($('#timeline'))$('#timeline').value=time;refresh();toast('已揭开全部提交，当前为最终榜单');break;case'reset-rules':rules={...DEFAULT_RULES};final=false;persist();renderRules();toast('已恢复题面默认规则');break;case'template':download(JSON.stringify(template,null,2),'ccpc-submissions-template.json');break;case'csv-template':download('\uFEFFname,school,A,B,C\r\nHello World,示例大学,+1 00:28,,-2\r\n无限可能,另一所大学,,+ 00:43,','ccpc-standings-template.csv','text/csv;charset=utf-8');break;}
});
$('#file-input').addEventListener('change',e=>readFile(e.target.files[0]));
const drop=$('#dropzone');for(const ev of ['dragenter','dragover'])drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('dragging');});for(const ev of ['dragleave','drop'])drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('dragging');if(ev==='drop')readFile(e.dataTransfer.files[0]);});
$('#parse-paste').addEventListener('click',()=>{if(new Blob([$('#paste-input').value]).size>20*1024*1024){$('#import-error').textContent='粘贴数据超过 20 MB';return;}parseData($('#paste-input').value);});
$('#download-template').addEventListener('click',()=>download(JSON.stringify(template,null,2),'ccpc-submissions-template.json'));
$('#confirm-import').addEventListener('click',()=>{if(!pendingImport)return;contests.push(pendingImport);currentId=pendingImport.id;time=pendingImport.submissions?0:pendingImport.duration;final=!pendingImport.submissions;pendingImport=null;persist();$('#import-dialog').close();goto('standings');toast('榜单已导入，可在历史赛事中再次查看');});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){const search=$('#search');if(search){e.preventDefault();search.focus();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['standings','history','rules','guide'].includes(p))goto(p);});
goto(['standings','history','rules','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'standings');if(storageWarning)toast('未能恢复上次数据，已载入演示赛事');
